  function savePurchaseDraft(){
    const backup=A.clone(D()),draft=S.purchaseDraft;if(!draft)return;
    try{
      syncPurchaseDraftFromInputs();const d=D();A.validateOpenFinancialDate?.(draft.date||A.today());if(!draft.lines.length)throw Error('أضف صنفاً واحداً على الأقل إلى الفاتورة.');const totals=purchaseDraftTotals(draft),paid=Math.max(0,num(draft.paid));if(paid>totals.total+.009)throw Error('المبلغ المدفوع أكبر من إجمالي الفاتورة.');const supplier=d.suppliers.find(x=>x.id===draft.supplierId),warehouse=d.warehouses.find(x=>x.id===draft.warehouseId);if(!warehouse)throw Error('اختر مستودعاً صحيحاً.');if(totals.total-paid>.009&&!supplier)throw Error('اختر مورداً حتى يُسجل المبلغ المتبقي كدين على المورد.');
      const lines=draft.lines.map(l=>{const p=d.products.find(x=>x.id===l.productId),u=A.productUnit(p,l.unitId);if(!p||!u)throw Error('يوجد صنف أو وحدة غير صالحة داخل الفاتورة.');const qty=Math.max(.00000001,num(l.qty)),unitCost=Math.max(0,num(l.unitCost)),taxRate=Math.max(0,num(l.taxRate)),grossSubtotal=qty*unitCost,discount=totals.grossSubtotal>0?totals.discount*(grossSubtotal/totals.grossSubtotal):0,subtotal=grossSubtotal-discount,tax=subtotal*taxRate/100,effectiveUnitCost=qty>0?subtotal/qty:unitCost;return{productId:p.id,productName:p.name,unitId:u.id,unitName:u.name,factor:num(u.factor||1),qty,baseQty:Number((qty*num(u.factor||1)).toFixed(8)),unitCost,effectiveUnitCost:Number(effectiveUnitCost.toFixed(6)),taxRate,grossSubtotal:Number(grossSubtotal.toFixed(2)),discount:Number(discount.toFixed(2)),subtotal:Number(subtotal.toFixed(2)),tax:Number(tax.toFixed(2)),total:Number((subtotal+tax).toFixed(2))}}),due=Number((totals.total-paid).toFixed(2));
      let target=d.purchases.find(x=>x.id===draft.editId),affected=new Set(lines.map(x=>x.productId));if(target){(target.lines||[]).forEach(l=>affected.add(l.productId));reversePurchase(target)}else target={id:A.uid('PUR'),number:A.nextNo('purchase',(d.settings.purchasePrefix||'PUR')+'-'),createdAt:A.now()};Object.assign(target,{date:draft.date||A.today(),supplierId:supplier?.id||'',supplierName:supplier?.name||'مورد نقدي',warehouseId:warehouse.id,branchId:warehouse.branchId,reference:draft.reference||'',lines,grossSubtotal:totals.grossSubtotal,discountMode:draft.discountMode||'amount',discountValue:num(draft.discountValue),discount:totals.discount,subtotal:totals.subtotal,tax:totals.tax,total:totals.total,paid,due,paymentAccountId:draft.paymentAccountId||'ACC-1110',status:due>0?'credit':'paid',updatedAt:A.now(),userId:A.currentUser().id,userName:A.currentUser().name});if(!draft.editId)d.purchases.unshift(target);applyPurchase(target);affected.forEach(recalcPurchasedCost);A.audit(draft.editId?'تعديل فاتورة شراء':'فاتورة شراء','المشتريات',`${target.number} — ${lines.length} صنف`);if(!A.saveDB())throw Error('تعذر حفظ فاتورة المشتريات في التخزين المحلي. تحقق من مساحة التخزين ثم أعد المحاولة.');S.purchaseDraft=null;A.toast(draft.editId?'تم تعديل الفاتورة وعكس الحركة القديمة':'تم حفظ فاتورة المشتريات وتحديث المخزون وذمة المورد');A.renderCurrent()
    }catch(e){A.db=backup;S.purchaseDraft=draft;A.saveDB(true);A.toast(e?.message||'تعذر حفظ فاتورة المشتريات.','error',5500);console.error('Purchase save error:',e)}
  }
  function deletePurchase(id){
    const d=D(),x=d.purchases.find(p=>p.id===id);if(!x)return;try{A.validateOpenFinancialDate?.(x.date)}catch(e){return A.toast(e.message,'error',5000)}if(!A.has('delete'))return A.toast('لا تملك صلاحية الحذف.','error');A.confirmDialog('حذف فاتورة الشراء',`${x.number} — سيتم عكس المخزون والحسابات والذمة ثم حذف السجل.`,()=>{const affected=[...new Set((x.lines||[]).map(l=>l.productId))];reversePurchase(x);d.purchases=d.purchases.filter(p=>p.id!==id);affected.forEach(recalcPurchasedCost);A.audit('حذف فاتورة شراء','المشتريات',x.number);A.saveDB();A.toast('تم حذف الفاتورة وعكس جميع حركاتها');A.renderCurrent()})
  }
