  const eanL=['0001101','0011001','0010011','0111101','0100011','0110001','0101111','0111011','0110111','0001011'],eanG=['0100111','0110011','0011011','0100001','0011101','0111001','0000101','0010001','0001001','0010111'],eanR=['1110010','1100110','1101100','1000010','1011100','1001110','1010000','1000100','1001000','1110100'],eanParity=['LLLLLL','LLGLGG','LLGGLG','LLGGGL','LGLLGG','LGGLLG','LGGGLL','LGLGLG','LGLGGL','LGGLGL'];
  function ean13Svg(input){let code=String(input).replace(/\D/g,'');if(code.length===12){const sum=code.split('').reduce((a,n,i)=>a+num(n)*(i%2?3:1),0);code+=(10-sum%10)%10}if(code.length!==13)throw Error('EAN-13 يحتاج 12 رقماً، وسيضاف رقم التحقق تلقائياً.');const parity=eanParity[num(code[0])];let bits='101';for(let i=1;i<=6;i++)bits+=(parity[i-1]==='L'?eanL:eanG)[num(code[i])];bits+='01010';for(let i=7;i<13;i++)bits+=eanR[num(code[i])];bits+='101';const mw=2,w=bits.length*mw+20,rects=[];for(let i=0;i<bits.length;i++)if(bits[i]==='1'){const guard=i<3||(i>=45&&i<50)||i>=92;rects.push(`<rect x="${10+i*mw}" y="4" width="${mw}" height="${guard?70:62}" fill="#000"/>`)}return{code,svg:`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${w} 92" width="${w}" height="92">${rects.join('')}<text x="${w/2}" y="88" text-anchor="middle" font-family="Arial" font-size="13" fill="#000">${code}</text></svg>`}}
  const c39={'0':'nnnwwnwnn','1':'wnnwnnnnw','2':'nnwwnnnnw','3':'wnwwnnnnn','4':'nnnwwnnnw','5':'wnnwwnnnn','6':'nnwwwnnnn','7':'nnnwnnwnw','8':'wnnwnnwnn','9':'nnwwnnwnn','A':'wnnnnwnnw','B':'nnwnnwnnw','C':'wnwnnwnnn','D':'nnnnwwnnw','E':'wnnnwwnnn','F':'nnwnwwnnn','G':'nnnnnwwnw','H':'wnnnnwwnn','I':'nnwnnwwnn','J':'nnnnwwwnn','K':'wnnnnnnww','L':'nnwnnnnww','M':'wnwnnnnwn','N':'nnnnwnnww','O':'wnnnwnnwn','P':'nnwnwnnwn','Q':'nnnnnnwww','R':'wnnnnnwwn','S':'nnwnnnwwn','T':'nnnnwnwwn','U':'wwnnnnnnw','V':'nwwnnnnnw','W':'wwwnnnnnn','X':'nwnnwnnnw','Y':'wwnnwnnnn','Z':'nwwnwnnnn','-':'nwnnnnwnw','.':'wwnnnnwnn',' ':'nwwnnnwnn','*':'nwnnwnwnn'};
  function code39Svg(input){let code=String(input).toUpperCase().replace(/[^0-9A-Z.\- ]/g,'');if(!code)throw Error('اكتب كوداً صحيحاً.');const chars=('*'+code+'*').split('');let x=8,rects=[];for(const ch of chars){const pat=c39[ch];for(let i=0;i<9;i++){const w=pat[i]==='w'?5:2;if(i%2===0)rects.push(`<rect x="${x}" y="4" width="${w}" height="60" fill="#000"/>`);x+=w}x+=2}const width=x+8;return{code,svg:`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${width} 82" width="${width}" height="82">${rects.join('')}<text x="${width/2}" y="78" text-anchor="middle" font-family="Arial" font-size="12" fill="#000">${esc(code)}</text></svg>`}}
  function makeBarcode(code,format='auto'){if(format==='ean13'||(format==='auto'&&/^\d{12,13}$/.test(code)))return ean13Svg(code);return code39Svg(code)}
  function renderBarcodes(root){const d=D(),preset=localStorage.getItem('almezan_barcode_product'),product=d.products.find(x=>x.id===preset)||d.products[0],unit=product?.units?.[0],code=S.barcodeCode||unit?.barcode||product?.sku||'',label=S.barcodeLabel||product?.name||'',format=S.barcodeFormat||'auto';let preview='';try{preview=makeBarcode(code,format).svg}catch(e){preview=`<div class="empty-state compact-empty"><p>${esc(e.message)}</p></div>`}root.innerHTML=`${A.pageHead('منشئ الباركود','إنشاء ملصقات EAN-13 وCode 39 وطباعتها',action('print-barcodes','طباعة الملصقات','print'))}<div class="grid-2"><article class="panel"><div class="form-grid"><label class="field"><span>اختيار صنف</span><select id="barcodeProduct"><option value="">إدخال يدوي</option>${A.options(d.products,'id','name',product?.id)}</select></label><label class="field"><span>الوحدة</span><select id="barcodeUnit">${product?A.options(product.units,'id','name',unit?.id):''}</select></label><label class="field"><span>الكود</span><input id="barcodeCode" value="${esc(code)}"></label><label class="field"><span>نوع الباركود</span><select id="barcodeFormat"><option value="auto">تلقائي</option><option value="ean13">EAN-13</option><option value="code39">Code 39</option></select></label><label class="field"><span>اسم الملصق</span><input id="barcodeLabel" value="${esc(label)}"></label><label class="field"><span>عدد النسخ</span><input id="barcodeCopies" type="number" min="1" max="100" value="${num(S.barcodeCopies)||1}"></label></div><div class="first-login-note">${I('info')} للأكواد الرقمية استخدم 12 رقماً وسيحسب النظام رقم التحقق الثالث عشر.</div></article><article class="panel"><div class="panel-head"><div><h3>معاينة الملصق</h3><p>${esc(label)}</p></div></div><div class="barcode-preview"><div class="barcode-label">${preview}<strong>${esc(label)}</strong></div></div></article></div>`;$('#barcodeFormat').value=format;function update(){S.barcodeCode=$('#barcodeCode').value;S.barcodeLabel=$('#barcodeLabel').value;S.barcodeFormat=$('#barcodeFormat').value;S.barcodeCopies=num($('#barcodeCopies').value)||1;A.renderCurrent()}['barcodeCode','barcodeLabel'].forEach(id=>{$('#'+id).onchange=update});$('#barcodeFormat').onchange=update;$('#barcodeCopies').onchange=update;$('#barcodeProduct').onchange=e=>{const p=d.products.find(x=>x.id===e.target.value);if(p){localStorage.setItem('almezan_barcode_product',p.id);S.barcodeCode=p.units?.[0]?.barcode||p.sku||'';S.barcodeLabel=p.name}else{localStorage.removeItem('almezan_barcode_product')}A.renderCurrent()};$('#barcodeUnit').onchange=e=>{const p=d.products.find(x=>x.id===$('#barcodeProduct').value),u=p?.units.find(x=>x.id===e.target.value);if(u)S.barcodeCode=u.barcode||'';A.renderCurrent()}}

  function renderPrint(hash){$('#loginScreen').hidden=true;$('#appShell').hidden=true;let view=$('.print-view');if(!view){view=document.createElement('div');view.className='print-view';document.body.appendChild(view)}document.body.classList.add('printing');let html='';if(hash.startsWith('print-invoice/')){const id=hash.split('/')[1],x=D().sales.find(s=>s.id===id);if(!x){html='<p>الفاتورة غير موجودة.</p>'}else{const settings=D().settings,thermal=settings.printSize!=='a4',cls=thermal?`thermal thermal-${settings.printSize}`:'',tax=x.tax||0,logoHtml=settings.showInvoiceLogo!==false?`<div class="print-brand print-brand-${esc(settings.invoiceLogoSize||'small')}"><img src="brand-logo.png" alt="شعار البرنامج"></div>`:'',barcodeHtml=settings.showInvoiceBarcode!==false?`<div class="invoice-barcode invoice-barcode-${esc(settings.invoiceBarcodeSize||'medium')}">${code39Svg(x.number).svg}</div>`:'';html=`<section class="print-sheet ${cls}"><header class="print-header">${logoHtml}<div class="print-company-block"><h2>${esc(D().company.name)}</h2><p>${esc(D().company.legalName||'')}</p><small>${esc(D().company.address||'')} ${esc(D().company.phone||'')}</small><br><small>الرقم الضريبي: ${esc(D().company.taxNumber||'—')}</small></div><div class="print-title"><b>فاتورة مبيعات</b><h3>${esc(x.number)}</h3></div></header><div class="print-meta"><div><b>التاريخ:</b> ${A.dateFmt(x.date)}</div><div><b>العميل:</b> ${esc(x.customerName)}</div><div><b>الفرع:</b> ${esc(A.branchName(x.branchId))}</div><div><b>الكاشير:</b> ${esc(x.userName||'—')}</div></div><table class="print-table"><thead><tr><th>#</th><th>الصنف</th><th>الوحدة</th><th>الكمية</th><th>السعر</th><th>الإجمالي</th></tr></thead><tbody>${x.lines.map((l,i)=>`<tr><td>${i+1}</td><td>${esc(l.productName)}</td><td>${esc(l.unitName)}</td><td>${l.qty}</td><td>${A.money(l.unitPrice)}</td><td>${A.money(l.total)}</td></tr>`).join('')}</tbody></table><div class="print-totals"><div><span>المجموع</span><b>${A.money(x.subtotal)}</b></div><div><span>الخصم</span><b>${A.money(x.discount)}</b></div><div><span>الضريبة</span><b>${A.money(tax)}</b></div><div class="grand"><span>الإجمالي</span><b>${A.money(x.total)}</b></div><div><span>المدفوع</span><b>${A.money(x.paid)}</b></div><div><span>المتبقي</span><b>${A.money(x.due)}</b></div></div>${barcodeHtml}<footer class="print-footer">${esc(D().company.invoiceNote||'شكراً لتعاملكم معنا')}</footer></section>`}}else if(hash==='print-report'){let r;try{r=JSON.parse(localStorage.getItem('almezan_report_print'))}catch(e){}if(r)html=`<section class="print-sheet"><header class="print-header"><div class="print-brand print-brand-small"><img src="brand-logo.png" alt="شعار المحل"></div><div><h2>${esc(D().company.name)}</h2><small>${esc(D().company.legalName||'')}</small><br><small>${esc(D().company.taxNumber||'')} ${esc(D().company.phone||'')}</small></div><div class="print-title"><h3>${esc(r.title)}</h3><small>${esc(r.from)} — ${esc(r.to)}</small></div></header><table class="print-table" style="margin-top:18px"><thead><tr>${r.headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${r.rows.map(row=>`<tr>${row.map(c=>`<td>${typeof c==='number'?A.money(c):esc(c)}</td>`).join('')}</tr>`).join('')}</tbody></table><div class="print-totals"><div class="grand"><span>الملخص</span><b>${esc(r.summary)}</b></div></div><footer class="print-footer">طبع بتاريخ ${A.dateFmt(A.now(),true)}</footer></section>`}else if(hash==='print-record'){let r;try{r=JSON.parse(localStorage.getItem('almezan_record_print'))}catch(e){}if(r)html=`<section class="print-sheet"><header class="print-header"><div class="print-brand print-brand-small"><img src="brand-logo.png" alt="شعار المحل"></div><div class="print-company-block"><h2>${esc(r.company?.name||D().company.name)}</h2><p>${esc(r.company?.legalName||D().company.legalName||'')}</p><small>${esc(r.company?.phone||D().company.phone||'')} ${esc(r.company?.address||D().company.address||'')}</small><br><small>الرقم الضريبي: ${esc(r.company?.taxNumber||D().company.taxNumber||'—')}</small></div><div class="print-title"><b>تقرير سجل</b><h3>${esc(r.title||'سجل')}</h3></div></header><table class="print-table" style="margin-top:18px"><thead><tr>${(r.headers||[]).map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody><tr>${(r.values||[]).map(v=>`<td>${esc(v)}</td>`).join('')}</tr></tbody></table><footer class="print-footer">${esc(D().company.name)} — طبع بتاريخ ${A.dateFmt(A.now(),true)}</footer></section>`}else if(hash==='print-barcodes'){let p;try{p=JSON.parse(localStorage.getItem('almezan_barcode_print'))}catch(e){}if(p){const b=makeBarcode(p.code,p.format);html=`<section class="print-sheet"><div class="barcode-sheet">${Array.from({length:p.copies},()=>`<div class="barcode-label">${b.svg}<strong>${esc(p.label)}</strong></div>`).join('')}</div></section>`;document.body.classList.add('barcode-print')}}view.innerHTML=html||'<p>لا توجد بيانات للطباعة.</p>';requestAnimationFrame(()=>setTimeout(()=>window.print(),90))}

