  function activeCustomerGroups(){return (D().customerGroups||[]).filter(x=>x.active!==false)}
  function customerGroup(customer){const d=D();return d.customerGroups.find(x=>x.id===customer?.customerGroupId)||d.customerGroups.find(x=>x.id==='CG-RETAIL')||d.customerGroups[0]||null}
  function priceGroupForCustomer(customer){const d=D(),cg=customerGroup(customer),id=customer?.priceGroupIdOverride||cg?.priceGroupId||d.settings.defaultPriceGroupId||'PG-RETAIL';return d.priceGroups.find(x=>x.id===id)||d.priceGroups.find(x=>x.id==='PG-RETAIL')||d.priceGroups[0]||null}
  function customerDiscountPercent(customer){const cg=customerGroup(customer);return Math.max(0,num(cg?.defaultDiscountPercent)+num(customer?.extraDiscountPercent))}
