      const data={id:group?.id||A.uid('CG'),name,code,priceGroupId:fd.get('priceGroupId'),defaultCreditLimit:num(fd.get('defaultCreditLimit')),paymentTermsDays:num(fd.get('paymentTermsDays')),defaultDiscountPercent:num(fd.get('defaultDiscountPercent')),active:fd.get('active')==='1',system:group?.system||false,createdAt:group?.createdAt||A.now(),updatedAt:A.now()};
      group?Object.assign(group,data):d.customerGroups.push(data);A.audit(group?'تعديل مجموعة عملاء':'إضافة مجموعة عملاء','مجموعات العملاء',name);A.saveDB();refreshPricingCache();A.toast('تم حفظ مجموعة العملاء');A.renderCurrent();
