  function payrollRow(worker,month){
    const d=D(),days=d.attendance.filter(x=>x.workerId===worker.id&&String(x.date).startsWith(month)),daily=num(worker.basicSalary)/30,hourly=daily/8,absent=days.filter(x=>x.status==='absent').length,lateMin=days.reduce((a,x)=>a+num(x.lateMinutes),0),otMin=days.reduce((a,x)=>a+num(x.overtimeMinutes),0),attendanceDeduction=absent*daily+(lateMin/60)*hourly,overtime=(otMin/60)*hourly*(num(worker.overtimeMultiplier)||1.5),adjust=d.payrollAdjustments.filter(x=>x.workerId===worker.id&&String(x.date).startsWith(month)),additions=adjust.filter(x=>x.type==='allowance').reduce((a,x)=>a+num(x.amount),0),deductions=adjust.filter(x=>x.type==='deduction').reduce((a,x)=>a+num(x.amount),0),loan=d.employeeLoans.find(x=>x.workerId===worker.id&&num(x.remaining)>0),loanDeduction=loan?Math.min(num(loan.installment),num(loan.remaining)):0,gross=num(worker.basicSalary)+num(worker.allowances)+overtime+additions,salaryExpense=Math.max(0,gross-attendanceDeduction),net=Math.max(0,salaryExpense-deductions-loanDeduction);return{workerId:worker.id,workerName:worker.name,basic:num(worker.basicSalary),allowances:num(worker.allowances)+additions,overtime:Number(overtime.toFixed(2)),attendanceDeduction:Number(attendanceDeduction.toFixed(2)),otherDeductions:Number(deductions.toFixed(2)),loanDeduction:Number(loanDeduction.toFixed(2)),loanId:loan?.id||'',salaryExpense:Number(salaryExpense.toFixed(2)),net:Number(net.toFixed(2))}
  }
