    if(type==='stockmove'){const rows=[];d.purchases.filter(x=>x.status!=='cancelled'&&between(x.date)).forEach(x=>(x.lines||[]).forEach(l=>rows.push([x.date,'شراء',l.productName,l.unitName,l.qty,l.baseQty,A.warehouseName(x.warehouseId)])));d.sales.filter(x=>x.status!=='returned'&&between(x.date)).forEach(x=>(x.lines||[]).filter(l=>l.trackStock!==false).forEach(l=>rows.push([x.date,'بيع',l.productName,l.unitName,-num(l.qty),-num(l.baseQty),A.warehouseName(x.warehouseId)])));d.transfers.filter(x=>x.status!=='cancelled'&&between(x.date)).forEach(x=>rows.push([x.date,'نقل',x.productName,x.unitName||'أساسية',x.unitQty||x.qty,x.baseQty||x.qty,`${A.warehouseName(x.fromId)} → ${A.warehouseName(x.toId)}`]));return{title:'حركة المخزون',headers:['التاريخ','الحركة','الصنف','الوحدة','الكمية','كمية أساسية','الموقع'],rows}}
    if(type==='reps')return{title:'عمولات المناديب',headers:['المندوب','المبيعات الصافية','نسبة العمولة','العمولة المستحقة'],rows:d.representatives.map(r=>{const sales=d.sales.filter(s=>s.status!=='returned'&&s.representativeId===r.id&&between(s.date)),value=sales.reduce((a,s)=>a+num(s.total)-num(s.tax),0),comm=sales.reduce((a,s)=>a+num(s.commissionAmount),0);return[r.name,value,`${num(r.commission)}%`,comm]})};
