  function openTransferPro(){const d=D();if(!d.products.length||d.warehouses.filter(x=>x.active).length<2)return A.toast('تحتاج صنفاً ومستودعين على الأقل.','warning');const p=d.products.find(x=>x.active!==false)||d.products[0];A.openModal({title:'نقل مخزني بالوحدة',size:'modal-lg',body:`<div class="form-grid cols-3"><label class="field"><span>التاريخ</span><input name="date" type="date" value="${A.today()}"></label><label class="field"><span>الصنف</span><select name="productId" id="trProduct">${A.options(d.products.filter(x=>x.active!==false))}</select></label><label class="field"><span>الوحدة</span><select name="unitId" id="trUnit">${A.options(p.units||[])}</select></label><label class="field"><span>من مستودع</span><select name="fromId">${A.options(d.warehouses.filter(x=>x.active))}</select></label><label class="field"><span>إلى مستودع</span><select name="toId">${A.options(d.warehouses.filter(x=>x.active))}</select></label><label class="field"><span>الكمية</span><input name="qty" type="number" min="0.00000001" step="any" value="1"></label><label class="field full"><span>ملاحظات / مرجع</span><input name="notes"></label></div>`,onSubmit:fd=>{const product=d.products.find(x=>x.id===fd.get('productId')),unit=A.productUnit(product,fd.get('unitId')),from=fd.get('fromId'),to=fd.get('toId'),unitQty=num(fd.get('qty')),baseQty=unitQty*num(unit.factor||1);if(from===to)throw Error('اختر مستودعين مختلفين.');if(product.trackStock===false)throw Error('الصنف غير مخزني ولا يحتاج نقل.');if(A.stockQty(product.id,from)+1e-8<baseQty)throw Error('الرصيد غير كافٍ في مستودع المصدر.');A.adjustStock(product.id,from,-baseQty);A.adjustStock(product.id,to,baseQty);const x={id:A.uid('TRF'),number:A.nextNo('transfer','TRF-'),date:fd.get('date'),productId:product.id,productName:product.name,unitId:unit.id,unitName:unit.name,factor:num(unit.factor||1),unitQty,baseQty,qty:baseQty,fromId:from,toId:to,notes:fd.get('notes'),status:'posted',createdAt:A.now(),userId:A.currentUser().id};d.transfers.unshift(x);A.audit('نقل مخزني','المخزون',`${x.number} — ${product.name} ${unitQty} ${unit.name}`);A.saveDB();A.toast('تم النقل وتحديث المستودعين');A.renderCurrent()},afterOpen:form=>{const ps=A.$('#trProduct',form),us=A.$('#trUnit',form);ps.onchange=()=>{const product=d.products.find(x=>x.id===ps.value);us.innerHTML=A.options(product.units||[]);A.enhanceSelects(form)}}})}
  function renderTransfersPro(root){const d=D();root.innerHTML=`${A.pageHead('النقل المخزني','',action('add-transfer','نقل جديد','transfer'))}<article class="panel">${A.table(['الرقم','التاريخ','الصنف','الوحدة','الكمية','من','إلى','الحالة','الإجراءات'],d.transfers.map(x=>`<tr><td class="text-primary">${esc(x.number)}</td><td>${A.dateFmt(x.date)}</td><td><b>${esc(x.productName)}</b></td><td>${esc(x.unitName||'أساسية')}</td><td>${num(x.unitQty||x.qty)} ${esc(x.unitName||'')}</td><td>${esc(A.warehouseName(x.fromId))}</td><td>${esc(A.warehouseName(x.toId))}</td><td>${A.badge(x.status==='cancelled'?'ملغي':'مرحّل',x.status==='cancelled'?'red':'green')}</td><td><div class="table-actions">${x.status!=='cancelled'?iconBtn('cancel-transfer','refresh','عكس',`data-id="${x.id}"`):''}${iconBtn('delete-transfer','trash','حذف',`data-id="${x.id}"`)}</div></td></tr>`),A.emptyState('transfer','لا توجد تحويلات',''))}</article>`}
  A.registerView('transfers',renderTransfersPro);A.registerAction('add-transfer',openTransferPro);A.registerAction('cancel-transfer',b=>{const d=D(),x=d.transfers.find(t=>t.id===b.dataset.id);if(!x||x.status==='cancelled')return;const q=num(x.baseQty||x.qty);if(A.stockQty(x.productId,x.toId)+1e-8<q)return A.toast('رصيد مستودع الوجهة أقل من كمية النقل ولا يمكن عكسه.','warning');A.confirmDialog('عكس النقل',x.number,()=>{A.adjustStock(x.productId,x.toId,-q);A.adjustStock(x.productId,x.fromId,q);x.status='cancelled';x.cancelledAt=A.now();A.audit('عكس نقل','المخزون',x.number);A.saveDB();A.renderCurrent()})});A.registerAction('delete-transfer',b=>{const d=D(),x=d.transfers.find(t=>t.id===b.dataset.id);if(!x)return;A.confirmDialog('حذف النقل',x.number,()=>{const q=num(x.baseQty||x.qty);if(x.status!=='cancelled'){if(A.stockQty(x.productId,x.toId)+1e-8<q)return A.toast('لا يمكن الحذف قبل توفر كمية العكس.','warning');A.adjustStock(x.productId,x.toId,-q);A.adjustStock(x.productId,x.fromId,q)}d.transfers=d.transfers.filter(t=>t.id!==x.id);A.audit('حذف نقل','المخزون',x.number);A.saveDB();A.renderCurrent()})});

