  function waPhone(v){return String(v||'').replace(/\D/g,'')}
  function templateText(template,customer,extra={}){return String(template?.body||'').replace(/\{customer\}/g,customer?.name||'').replace(/\{amount\}/g,extra.amount!=null?A.money(extra.amount):A.money(customer?.balance||0)).replace(/\{due_date\}/g,extra.dueDate?A.dateFmt(extra.dueDate):'').replace(/\{installment_no\}/g,String(extra.installmentNo||''))}
  function openTemplate(item=null){A.openModal({title:item?'تعديل قالب رسالة':'قالب رسالة جديد',body:`<div class="form-grid"><label class="field"><span>اسم القالب</span><input name="name" required value="${esc(item?.name||'')}"></label><label class="field"><span>القناة</span><select name="channel"><option value="all" ${item?.channel==='all'?'selected':''}>واتساب وSMS</option><option value="whatsapp" ${item?.channel==='whatsapp'?'selected':''}>واتساب</option><option value="sms" ${item?.channel==='sms'?'selected':''}>SMS</option></select></label><label class="field full"><span>نص الرسالة</span><textarea name="body" rows="5" required>${esc(item?.body||'مرحباً {customer}، ')}</textarea></label></div><div class="first-login-note">المتغيرات: {customer} اسم العميل، {amount} المبلغ، {due_date} تاريخ الاستحقاق، {installment_no} رقم القسط.</div>`,onSubmit:fd=>{const data=item||{id:A.uid('TPL'),createdAt:A.now()};Object.assign(data,{name:fd.get('name').trim(),channel:fd.get('channel'),body:fd.get('body').trim(),updatedAt:A.now()});if(!item)D().messageTemplates.push(data);A.audit(item?'تعديل قالب':'إضافة قالب','رسائل العملاء',data.name);A.saveDB();A.renderCurrent()}})}
  function renderMessaging(root){const d=D(),customers=d.customers.filter(x=>!x.system&&x.active),templates=d.messageTemplates;S.messageTemplateId=S.messageTemplateId||templates[0]?.id||'';const current=templates.find(x=>x.id===S.messageTemplateId)||templates[0];root.innerHTML=`${A.pageHead('رسائل العملاء','',action('add-message-template','قالب جديد','plus'))}<section class="messaging-toolbar panel"><label class="field"><span>قالب الرسالة</span><select id="messageTemplateSelect">${A.options(templates,'id','name',current?.id)}</select></label><label class="field message-preview-field"><span>معاينة النص</span><textarea id="messageTemplatePreview" rows="3">${esc(current?.body||'')}</textarea></label></section><article class="panel"><div class="panel-head"><div><h3>العملاء</h3></div></div>${A.table(['العميل','الهاتف','الرصيد','واتساب','SMS','اتصال'],customers.map(c=>`<tr><td><b>${esc(c.name)}</b></td><td>${esc(c.phone||'—')}</td><td>${A.money(c.balance)}</td><td>${iconBtn('customer-whatsapp','whatsapp','واتساب',`data-id="${c.id}"`)}</td><td>${iconBtn('customer-sms','chat','رسالة جوال',`data-id="${c.id}"`)}</td><td>${iconBtn('customer-call','phone','اتصال',`data-id="${c.id}"`)}</td></tr>`),A.emptyState('customer','لا يوجد عملاء',''))}</article><article class="panel" style="margin-top:12px"><div class="panel-head"><div><h3>قوالب الرسائل</h3></div></div>${A.table(['الاسم','القناة','النص','الإجراءات'],templates.map(t=>`<tr><td><b>${esc(t.name)}</b></td><td>${esc(t.channel)}</td><td class="template-snippet">${esc(t.body)}</td><td><div class="table-actions">${iconBtn('edit-message-template','edit','تعديل',`data-id="${t.id}"`)}${t.system?'':iconBtn('delete-message-template','trash','حذف',`data-id="${t.id}"`)}</div></td></tr>`))}</article>`;$('#messageTemplateSelect').onchange=e=>{S.messageTemplateId=e.target.value;const t=d.messageTemplates.find(x=>x.id===e.target.value);$('#messageTemplatePreview').value=t?.body||''}}
  function messageCustomer(id,channel,extra={}){const d=D(),c=d.customers.find(x=>x.id===id);if(!c)return;const phone=cleanPhone(c.phone),template=d.messageTemplates.find(x=>x.id===S.messageTemplateId)||d.messageTemplates[0],text=extra.text||templateText(template,c,extra);if(!phone)return A.toast('لا يوجد رقم هاتف لهذا العميل.','warning');d.customerMessages.unshift({id:A.uid('CMSG'),customerId:c.id,channel,templateId:template?.id||'',text,createdAt:A.now(),userId:A.currentUser().id,status:'opened'});A.saveDB();if(channel==='whatsapp')window.open(`https://wa.me/${waPhone(phone)}?text=${encodeURIComponent(text)}`,'_blank');else if(channel==='sms')location.href=`sms:${phone}?body=${encodeURIComponent(text)}`;else location.href=`tel:${phone}`}
  A.registerView('messaging',renderMessaging);A.registerAction('add-message-template',()=>openTemplate());A.registerAction('edit-message-template',b=>openTemplate(D().messageTemplates.find(x=>x.id===b.dataset.id)));A.registerAction('delete-message-template',b=>{const t=D().messageTemplates.find(x=>x.id===b.dataset.id);if(!t||t.system)return;A.confirmDialog('حذف القالب',t.name,()=>{D().messageTemplates=D().messageTemplates.filter(x=>x.id!==t.id);A.saveDB();A.renderCurrent()})});A.registerAction('customer-whatsapp',b=>messageCustomer(b.dataset.id,'whatsapp'));A.registerAction('customer-sms',b=>messageCustomer(b.dataset.id,'sms'));A.registerAction('customer-call',b=>messageCustomer(b.dataset.id,'call'));A.registerAction('installment-whatsapp',b=>{const c=D().installmentContracts.find(x=>x.id===b.dataset.id),r=c&&firstOutstanding(c),customer=c&&D().customers.find(x=>x.id===c.customerId);if(!c||!r||!customer)return;messageCustomer(customer.id,'whatsapp',{amount:num(r.dueAmount)-num(r.paidAmount),dueDate:r.dueDate,installmentNo:r.installmentNo,text:templateText(D().messageTemplates.find(x=>x.id==='TPL-INSTALLMENT-DUE'),customer,{amount:num(r.dueAmount)-num(r.paidAmount),dueDate:r.dueDate,installmentNo:r.installmentNo})})});

  // Route sale edit/return/delete safely when the invoice belongs to an installment contract.
