  A.registerAction('delete-sale',b=>{const d=D(),sale=d.sales.find(x=>x.id===b.dataset.id),contract=sale&&d.installmentContracts.find(c=>c.saleId===sale.id&&c.status!=='cancelled');if(!contract)return baseDeleteSale?.(b);A.confirmDialog('حذف فاتورة أقساط',`${sale.number} — سيتم عكس العقد بالكامل ثم حذف الفاتورة من قائمة المبيعات.`,()=>{reverseInstallment(contract);d.sales=d.sales.filter(x=>x.id!==sale.id);A.audit('حذف فاتورة أقساط','الفواتير',sale.number);A.saveDB();A.renderCurrent()})});
