    if(!catNames.length)catNames.push('عام');
    for(const name of catNames){let c=d.categories.find(x=>x.name===name);if(!c){c={id:A.uid('CAT'),name,active:true,createdAt:A.now()};d.categories.push(c)}for(const p of d.products.filter(p=>(p.category||'عام')===name&&!p.categoryId))p.categoryId=c.id}
    if(!d.currencies.length){d.currencies.push({id:'CUR-BASE',code:'ILS',name:'شيكل',symbol:'₪',isBase:true,decimals:2,active:true,createdAt:A.now()})}
    let base=d.currencies.find(x=>x.isBase)||d.currencies[0];d.currencies.forEach(x=>x.isBase=x.id===base.id);Object.assign(base,{code:'ILS',name:'شيكل',symbol:'₪',isBase:true,active:true,decimals:2});d.settings.baseCurrencyId=base.id;d.company.currency='₪';
    for(const j of d.journals||[])for(const l of j.lines||[]){l.currencyId=l.currencyId||base.id;l.exchangeRate=num(l.exchangeRate)||1;const local=Math.max(num(l.debit),num(l.credit));if(l.foreignAmount==null)l.foreignAmount=local;if(l.localAmount==null)l.localAmount=local;if(l.foreignDebit==null)l.foreignDebit=num(l.debit);if(l.foreignCredit==null)l.foreignCredit=num(l.credit);if(l.localDebit==null)l.localDebit=num(l.debit);if(l.localCredit==null)l.localCredit=num(l.credit)}
    if(!d.costCenters.length)d.costCenters.push({id:'CC-GENERAL',code:'GENERAL',name:'المركز العام',parentId:'',active:true,system:true,createdAt:A.now()});
    d.settings.defaultCostCenterId=d.settings.defaultCostCenterId||d.costCenters[0].id;d.settings.shiftPostingMode=d.settings.shiftPostingMode||'batch';
    const y=new Date().getFullYear(),start=`${y}-01-01`,end=`${y}-12-31`;
    if(!d.financialYears.length)d.financialYears.push({id:`FY-${y}`,name:`السنة المالية ${y}`,startDate:start,endDate:end,status:'open',createdAt:A.now()});d.settings.currentFinancialYearId=d.settings.currentFinancialYearId||d.financialYears.find(x=>x.status==='open'&&A.today()>=x.startDate&&A.today()<=x.endDate)?.id||d.financialYears.find(x=>x.status==='open')?.id||'';repairFinancialYearState(d);
    const accts=[
      {id:'ACC-1510',code:'1510',name:'عجز الصندوق على الموظفين',type:'asset',parentId:'ACC-1000',level:1},
      {id:'ACC-2250',code:'2250',name:'مبيعات كاشير غير مرحلة',type:'liability',parentId:'ACC-2000',level:1},
      {id:'ACC-3100',code:'3100',name:'الأرباح المحتجزة',type:'equity',parentId:'ACC-3000',level:1},
      {id:'ACC-3200',code:'3200',name:'الأرصدة الافتتاحية',type:'equity',parentId:'ACC-3000',level:1},
      {id:'ACC-4210',code:'4210',name:'أرباح فروق العملة',type:'revenue',parentId:'ACC-4000',level:1},
      {id:'ACC-4220',code:'4220',name:'زيادة الصندوق',type:'revenue',parentId:'ACC-4000',level:1},
      {id:'ACC-4230',code:'4230',name:'أرباح تسوية المخزون',type:'revenue',parentId:'ACC-4000',level:1},
      {id:'ACC-5210',code:'5210',name:'خسائر فروق العملة',type:'expense',parentId:'ACC-5000',level:1},
      {id:'ACC-5220',code:'5220',name:'فروقات الصندوق',type:'expense',parentId:'ACC-5000',level:1},
      {id:'ACC-5230',code:'5230',name:'خسائر وتسويات المخزون',type:'expense',parentId:'ACC-5000',level:1}
    ];
